import json
steps=[]
for line in open('metrics.jsonl'):
    d=json.loads(line)
    data=d['data']
    if any(k.startswith('val-core') for k in data):
        v={k:v for k,v in data.items() if k.startswith('val-')}
        steps.append((d['step'],v))
for s,v in steps:
    print(s, v)
EOF

