arguments.command:
python3 - <<'EOF'
import json,re
def contains_gold(s,g):
    # any number token equal to gt, numeric
    nums=re.findall(r"\-?\d[\d,]*(?:\.\d+)?",s)
    try: gt=float(g)
    except: return False
    for n in nums:
        try:
            if float(n.replace(',',''))==gt: return True
        except: pass
    return False
def strict(s):
    t=s[-300:]
    m=re.findall(r"#### (\-?[0-9\.\,]+)",t)
    return m[-1].replace(',','') if m else None
def eq(p,g):
    try: return float(p)==float(g)
    except: return False
for f in ['rollouts/1.jsonl','rollouts/50.jsonl','rollouts/100.jsonl']:
    rows=[json.loads(l) for l in open(f)]
    obs=sum(r['score'] for r in rows)/len(rows)
    anyg=sum(contains_gold(r['output'],r['gts']) for r in rows)/len(rows)
    strictn=sum(eq(strict(r['output']),r['gts']) for r in rows)/len(rows)
    print(f,'observed',round(obs,3),'contains_gold_anywhere',round(anyg,3),'strict_numeric',round(strictn,3))
EOF

